function Button({ children, variant = 'primary', size = '', className = '', icon: Icon, iconRight = true, ...props }) {
  return <button className={cn('button', `button-${variant}`, size && `button-${size}`, className)} {...props}>
    {Icon && !iconRight && <Icon size={16} />}{children}{Icon && iconRight && <Icon size={16} />}
  </button>;
}

function Glass({ children, className = '', ...props }) { return <div className={cn('glass', className)} {...props}>{children}</div>; }

function Modal({ open, onClose, title, subtitle, children, wide = false }) {
  useEffect(() => {
    const close = (e) => e.key === 'Escape' && onClose?.();
    window.addEventListener('keydown', close);
    return () => window.removeEventListener('keydown', close);
  }, [onClose]);
  return <AnimatePresence>{open && <motion.div className="modal-backdrop" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onMouseDown={onClose}>
    <motion.div className={cn('modal', wide && 'modal-wide')} initial={{ opacity: 0, y: 18, scale: .98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 10, scale: .98 }} onMouseDown={e => e.stopPropagation()}>
      <div className="modal-header"><div><h3>{title}</h3>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" onClick={onClose}><X size={18}/></button></div>
      {children}
    </motion.div>
  </motion.div>}</AnimatePresence>;
}

function Toast({ message }) { return <AnimatePresence>{message && <motion.div className="toast" initial={{ y: 24, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 24, opacity: 0 }}><CheckCircle2 size={17}/>{message}</motion.div>}</AnimatePresence>; }

